// Calendar dates avoid daylight-saving offsets. Today follows the workflow timezone.
const day = 86400000;
const calendar = value => value ? Date.parse(value.slice(0,10) + 'T00:00:00Z') : NaN;
const today = calendar($now.toISODate());
return $input.all().filter(item => {
  const p = item.json.body;
  if (item.json.deleted || p.is_consumed || !(p.quantity > 0)) return false;
  let expiry = calendar(p.expiration_date);
  if (p.is_opened && p.opened_date && Number.isInteger(p.shelf_life_after_opening)) {
    const opened = calendar(p.opened_date) + p.shelf_life_after_opening * day;
    if (!Number.isFinite(expiry) || opened < expiry) expiry = opened;
  }
  if (!Number.isFinite(expiry)) return false;
  item.json.days_until = Math.round((expiry - today) / day);
  return item.json.days_until <= 7;
});
